package watch

import (
	"io/fs"
	"log/slog"
	"os"
	"path/filepath"
	"strings"

	"github.com/fsnotify/fsnotify"
)

// watchSet is the adapter's watch bookkeeping (D3, the thin shell): ONE
// fsnotify watcher, the current library-root set, and the directories
// actually registered with it. Owned by the Run loop goroutine alone —
// no locking.
type watchSet struct {
	w     *fsnotify.Watcher
	roots map[string]int64 // library root path -> library id (the CURRENT set)
	dirs  map[string]bool  // directories registered with the watcher
}

func newWatchSet(w *fsnotify.Watcher) *watchSet {
	return &watchSet{w: w, roots: make(map[string]int64), dirs: make(map[string]bool)}
}

// addRoot registers a library root and recursively installs watches on
// its directory tree. An already-registered root is left untouched.
func (ws *watchSet) addRoot(root string, id int64) {
	root = filepath.Clean(root)
	if _, ok := ws.roots[root]; ok {
		return
	}
	ws.roots[root] = id
	ws.installTree(root)
}

// removeRoot drops a deleted library root: its watches are removed and
// events under it map to no owner afterwards.
func (ws *watchSet) removeRoot(root string) {
	root = filepath.Clean(root)
	delete(ws.roots, root)
	ws.dropUnder(root)
}

// installTree walks root and registers every directory with the watcher.
// Per-directory failures log WARN and continue — watch exhaustion (a full
// inotify table) degrades convergence to the reconcile cadence, never to
// zero (design Risks: inotify watch exhaustion).
func (ws *watchSet) installTree(root string) {
	walkErr := fs.WalkDir(os.DirFS(root), ".", func(rel string, d fs.DirEntry, err error) error {
		if err != nil {
			if rel != "." {
				slog.Warn("watch: tree walk failed", "dir", filepath.Join(root, rel), "error", err)
			}
			return nil // skip the unreadable subtree, keep walking
		}
		if !d.IsDir() {
			return nil
		}
		dir := root
		if rel != "." {
			dir = filepath.Join(root, rel)
		}
		if err := ws.w.Add(dir); err != nil {
			slog.Warn("watch: add failed", "dir", dir, "error", err)
			return nil
		}
		ws.dirs[dir] = true
		return nil
	})
	if walkErr != nil {
		slog.Warn("watch: tree walk failed", "dir", root, "error", walkErr)
	}
}

// dropUnder unregisters every watched directory at or below dir. Remove
// errors are ignored: on inotify the kernel has already torn down the
// watches of a deleted directory, so failures here are the benign kind.
func (ws *watchSet) dropUnder(dir string) {
	dir = filepath.Clean(dir)
	sep := string(filepath.Separator)
	for watched := range ws.dirs {
		if watched == dir || strings.HasPrefix(watched, dir+sep) {
			_ = ws.w.Remove(watched)
			delete(ws.dirs, watched)
		}
	}
}

// owner maps a filesystem path to its owning library id by longest
// prefix over the CURRENT root set; an event outside every root maps to
// no owner and is ignored by the loop.
func (ws *watchSet) owner(path string) (int64, bool) {
	path = filepath.Clean(path)
	sep := string(filepath.Separator)
	bestLen := -1
	var best int64
	for root, id := range ws.roots {
		if (path == root || strings.HasPrefix(path, root+sep)) && len(root) > bestLen {
			bestLen, best = len(root), id
		}
	}
	return best, bestLen >= 0
}

// libraryIDs lists the ids behind the current root set (deduplicated —
// the set is one root per library, the dedup is defense in depth).
func (ws *watchSet) libraryIDs() []int64 {
	ids := make([]int64, 0, len(ws.roots))
	seen := make(map[int64]bool, len(ws.roots))
	for _, id := range ws.roots {
		if !seen[id] {
			seen[id] = true
			ids = append(ids, id)
		}
	}
	return ids
}
